// 模拟一个占用资源的对象，例如打开的连接或解码器
function openConnection(name: string) {
  console.log(`打开 ${name}`)
  return { name }
}

const connection = createStoreResource(() => openConnection('连接 #1'), {
  keepAliveMs: 20, // 没人使用后再保留 20ms
