const decoder = createStoreResource(
  () => {
    opened++
    console.log(`创建解码器 #${opened}`)
    return { id: opened }
  },
  { dispose: (value) => console.log(`释放解码器 #${value.id}`) }
)

const release = decoder.retainResource()
